	const version = Number(rows[0].state) || 0;
	this.ctx.storage.kv.put(SCHEMA_VERSION_KEY, version);
	this.ctx.storage.sql.exec("DELETE FROM cf_agents_state WHERE id = ?", LEGACY_SCHEMA_VERSION_ROW_ID);
